// Authored metre-scale landmarks. Source micro-hexes are not Board cells.
export const HERO_SCENES={castle:{label:'Castle',name:'Castle precinct',presets:{sunward:'Sunward castle',iron:'Iron Crown'},purpose:'Anchor a settlement with a recognizable protected landmark and public approach.',uses:['residents','visitors'],inputs:[],outputs:['landmark'],capabilities:{},limitations:['Static exterior assembly','Castle interior navigation, defense and administration are not simulated']}};
export function castleRequirements(preset){if(!HERO_SCENES.castle.presets[preset])throw Error('Unknown castle preset');return [{role:'castle',w:40.4,d:43.6,radius:29.7,anchor:{x:0,z:-3},hub:{x:0,z:35},exteriorAccess:{x:0,z:23},visualPaths:[{width:2.5,points:[{x:0,z:26},{x:0,z:17.35}]}],items:[{asset:preset==='iron'?'EH-002.iron-crown':'EH-001.sunward-castle',x:0,z:0,y:0,angle:0,purpose:'reviewed static castle and gate approach'}],purpose:HERO_SCENES.castle.purpose,index:0}];}
export function castleRecipe(preset,seed){return {generator:'castle-composer',version:1,type:'castle',preset,seed,requirements:castleRequirements(preset),landscape:{height:0,vegetation:1,props:0,seed:seed^173},tiles:[{id:'castle',type:'castle',cell:0,rotation:0,seed}]};}
export function describeCastle(preset){return `${HERO_SCENES.castle.presets[preset]} anchors the surrounding settlement. The keep, walls and gateway retain their reviewed metre-scale arrangement. A public approach meets the exterior precinct; interior traversal and defense remain undecided.`;}
